import{_ as t,g as d,e as a,a4 as r}from"./chunks/framework.CEYJDsBW.js";const f=JSON.parse('{"title":"Adjusting Client Preferences and Preview","description":"","frontmatter":{},"headers":[],"relativePath":"en/ageratum/26.1/reader/preferences.md","filePath":"en/ageratum/26.1/reader/preferences.md"}'),o={name:"en/ageratum/26.1/reader/preferences.md"};function n(c,e,i,l,s,u){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="adjusting-client-preferences-and-preview" tabindex="-1">Adjusting Client Preferences and Preview <a class="header-anchor" href="#adjusting-client-preferences-and-preview" aria-label="Permalink to &quot;Adjusting Client Preferences and Preview&quot;">​</a></h1><p>These options are managed by <code>AgeratumClientConfig</code> on the client. When accessing Java fields via <code>AgeratumClient.CONFIG</code>, keep calls on the physical client. Theme buttons handle saving the current configuration.</p><table tabindex="0"><thead><tr><th>Java Field</th><th>Type</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td><code>darkMode</code></td><td>boolean</td><td>false</td><td>Body color scheme and guide textures.</td></tr><tr><td><code>reducedMotion</code></td><td>boolean</td><td>false</td><td>Reduces motion in structure previews, keeping gentler transitions.</td></tr><tr><td><code>breadCrumbsHasLabel</code></td><td>boolean</td><td>false</td><td>Whether sidebar page switches enter breadcrumb history.</td></tr><tr><td><code>showCodeBlockLineNumbers</code></td><td>boolean</td><td>true</td><td>Code block line numbers.</td></tr><tr><td><code>allowCodeBlockLineContentLineBreaks</code></td><td>boolean</td><td>true</td><td>Whether long code lines are allowed to wrap.</td></tr><tr><td><code>enablePreview</code></td><td>boolean</td><td>false</td><td>Enables development preview.</td></tr><tr><td><code>previewPath</code></td><td>String</td><td><code>ageratum_preview</code></td><td>Development preview directory; relative paths are resolved against the game directory.</td></tr><tr><td><code>shareGuideOnlyInTeam</code></td><td>boolean</td><td>false</td><td>Whether sharing filters to teammates by default.</td></tr><tr><td><code>itemBindingHoldDurationMs</code></td><td>int</td><td>750</td><td>Milliseconds required to hold the item navigation key, allowed <code>100</code> to <code>5000</code>.</td></tr><tr><td><code>scale</code></td><td>double</td><td>1.0</td><td>Guide logical scale, a decimal allowed from <code>0.5</code> to <code>4.0</code>.</td></tr><tr><td><code>directorySide</code></td><td><code>DirectorySide</code></td><td><code>LEFT</code></td><td>Determines the final side of the panel containing the directory; accepts <code>LEFT</code> or <code>RIGHT</code>.</td></tr></tbody></table><p>When testing a single page you are editing, enable preview and open it with <code>/ageratum preview</code>. When verifying resource pack overrides, language fallback, and item indexes, place files back into the formal <code>assets</code> directory and reload resources.</p><p><a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/AgeratumClientConfig.java" target="_blank" rel="noreferrer">Config fields</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/layout/GuideLayoutManager.java" target="_blank" rel="noreferrer">Active layout selection</a></p>',5)])])}const g=t(o,[["render",n]]);export{f as __pageData,g as default};
